import { act, render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { Profiler } from 'react';

import { createPlayerStore } from '../player';
import type { PlayerAudio, PlayerQueueItem, PlayerStore } from '../player';
import { NowPlayingAside } from './NowPlayingAside';

class AsideAudio implements PlayerAudio {
  src = '';
  currentTime = 0;
  duration = 180;
  volume = 1;
  muted = false;
  paused = true;
  ended = false;
  error = null;
  playbackRate = 1;
  preload = '';
  private readonly listeners = new Map<string, Set<() => void>>();
  async play(): Promise<void> { this.paused = false; this.emit('playing'); }
  pause(): void { this.paused = true; this.emit('pause'); }
  load(): void {}
  addEventListener(type: string, listener: () => void): void {
    const group = this.listeners.get(type) ?? new Set();
    group.add(listener);
    this.listeners.set(type, group);
  }
  removeEventListener(type: string, listener: () => void): void {
    this.listeners.get(type)?.delete(listener);
  }
  emit(type: string): void { this.listeners.get(type)?.forEach((listener) => listener()); }
}

const tracks: PlayerQueueItem[] = [
  {
    id: 'current',
    title: 'Still Water',
    artworkUrl: '/art/still-water.jpg',
    artistNames: ['Aster Vale'],
    mediaType: 'audio',
    streamUrl: '/audio/still-water.mp3'
  },
  {
    id: 'next',
    title: 'Open Field',
    artworkUrl: '/art/open-field.jpg',
    artistNames: ['June North'],
    mediaType: 'audio',
    streamUrl: '/audio/open-field.mp3'
  }
];

const stores: PlayerStore[] = [];

afterEach(() => {
  act(() => stores.splice(0).forEach((store) => store.destroy()));
});

test('renders a quiet read-only state until the shared player has a current soundtrack', () => {
  const store = createPlayerStore({ audioFactory: () => new AsideAudio(), mediaSession: null });
  stores.push(store);
  render(<NowPlayingAside store={store} />);

  const panel = screen.getByRole('region', { name: 'Current MediaTrack' });
  expect(panel).toHaveTextContent('Nothing playing');
  expect(within(panel).queryByRole('button')).not.toBeInTheDocument();
});

test('shows only current metadata and the store-derived effective next item', async () => {
  const store = createPlayerStore({ audioFactory: () => new AsideAudio(), mediaSession: null });
  stores.push(store);
  await store.launchQueue(tracks, 0, { autoplay: false });
  render(<NowPlayingAside store={store} />);

  const aside = screen.getByRole('region', { name: 'Current MediaTrack' });
  expect(within(aside).getAllByText('Still Water')).toHaveLength(2);
  expect(within(aside).getByText('Aster Vale')).toBeInTheDocument();
  const upNext = within(aside).getByRole('region', { name: 'Up next' });
  expect(within(upNext).getByText('Open Field')).toBeInTheDocument();
  expect(within(upNext).getByText('June North')).toBeInTheDocument();
  expect(within(aside).queryByRole('button')).not.toBeInTheDocument();
});

test('labels the current soundtrack honestly when Repeat One is effective', async () => {
  const store = createPlayerStore({ audioFactory: () => new AsideAudio(), mediaSession: null });
  stores.push(store);
  await store.launchQueue(tracks, 0, { autoplay: false });
  store.cycleRepeatMode();
  store.cycleRepeatMode();
  render(<NowPlayingAside store={store} />);

  expect(screen.getByRole('region', { name: 'Repeats next' })).toHaveTextContent('Still Water');
});

test('a Video MediaTrack shows the playback queue and no media-mode switch', async () => {
  const audio = new AsideAudio();
  const audioFactory = vi.fn(() => audio);
  const store = createPlayerStore({ audioFactory, mediaSession: null });
  stores.push(store);
  await store.launchQueue([
    { ...tracks[0], mediaType: 'video', streamUrl: '/video/still-water.mp4' },
    tracks[1]
  ], 0, { autoplay: false });
  render(<NowPlayingAside store={store} />);

  const queue = screen.getByRole('region', { name: 'Video playback queue' });
  expect(within(queue).getByRole('heading', { name: 'Up next' })).toBeInTheDocument();
  expect(within(queue).getByText('Open Field')).toBeInTheDocument();
  expect(within(queue).queryByRole('group', { name: 'Playback media' })).not.toBeInTheDocument();
  expect(audio.src).toBe('/video/still-water.mp4');
  expect(audioFactory).toHaveBeenCalledTimes(1);
});

test('a minimized Video plays at the top of the panel, returns to the theater, and offers fullscreen', async () => {
  const user = userEvent.setup();
  // A real element lets the panel host it and request fullscreen on it; jsdom cannot load media.
  const video = document.createElement('video');
  video.load = () => undefined;
  video.pause = () => undefined;
  const requestFullscreen = vi.fn(async () => undefined);
  video.requestFullscreen = requestFullscreen;
  const store = createPlayerStore({ audioFactory: () => video, mediaSession: null });
  stores.push(store);
  await store.launchQueue([{ ...tracks[0], mediaType: 'video', streamUrl: '/video/still-water.mp4' }], 0, { autoplay: false });
  const onTheaterMinimized = vi.fn();
  const view = render(<NowPlayingAside onTheaterMinimized={onTheaterMinimized} store={store} theaterMinimized />);

  const surface = screen.getByRole('img', { name: 'Still Water video' });
  expect(surface).toContainElement(video);
  await user.click(screen.getByRole('button', { name: 'Still Water video' }));
  expect(onTheaterMinimized).toHaveBeenCalledWith(false);

  await user.click(screen.getByRole('button', { name: 'Enter video fullscreen' }));
  expect(requestFullscreen).toHaveBeenCalledTimes(1);
  expect(video.controls).toBe(true);

  // Exiting fullscreen restores the custom surface without replacing the playing element.
  act(() => { document.dispatchEvent(new Event('fullscreenchange')); });
  expect(video.controls).toBe(false);
  expect(screen.getByRole('img', { name: 'Still Water video' })).toContainElement(video);

  view.rerender(<NowPlayingAside onTheaterMinimized={onTheaterMinimized} store={store} />);
  expect(screen.queryByRole('img', { name: 'Still Water video' })).not.toBeInTheDocument();
  expect(screen.queryByRole('button', { name: 'Enter video fullscreen' })).not.toBeInTheDocument();
});

test.each(['unsupported', 'rejected'] as const)('a %s fullscreen request keeps the panel player usable', async (failure) => {
  const user = userEvent.setup();
  const video = document.createElement('video');
  video.load = () => undefined;
  video.pause = () => undefined;
  if (failure === 'rejected') video.requestFullscreen = vi.fn().mockRejectedValue(new Error('Fullscreen unavailable'));
  const store = createPlayerStore({ audioFactory: () => video, mediaSession: null });
  stores.push(store);
  await store.launchQueue([{ ...tracks[0], mediaType: 'video', streamUrl: '/video/still-water.mp4' }], 0, { autoplay: false });
  const before = store.getSnapshot();
  const onTheaterMinimized = vi.fn();
  render(<NowPlayingAside onTheaterMinimized={onTheaterMinimized} store={store} theaterMinimized />);

  await user.click(screen.getByRole('button', { name: 'Enter video fullscreen' }));

  expect(video.controls).toBe(false);
  expect(video).toHaveAttribute('aria-hidden', 'true');
  expect(store.getSnapshot()).toBe(before);
  expect(screen.getByRole('img', { name: 'Still Water video' })).toContainElement(video);
  await user.click(screen.getByRole('button', { name: 'Still Water video' }));
  expect(onTheaterMinimized).toHaveBeenCalledWith(false);
});

test('focus inside the minimized Video moves to the player-bar Video toggle when it leaves', async () => {
  const store = createPlayerStore({ audioFactory: () => new AsideAudio(), mediaSession: null });
  stores.push(store);
  await store.launchQueue([{ ...tracks[0], mediaType: 'video', streamUrl: '/video/still-water.mp4' }], 0, { autoplay: false });
  const panel = (minimized: boolean) => (
    <>
      <NowPlayingAside onTheaterMinimized={vi.fn()} store={store} theaterMinimized={minimized} />
      <button id="video-theater-toggle" type="button">Video</button>
    </>
  );
  const view = render(panel(true));
  screen.getByRole('button', { name: 'Enter video fullscreen' }).focus();

  view.rerender(panel(false));
  await act(async () => { await Promise.resolve(); });
  expect(screen.getByRole('button', { name: 'Video' })).toHaveFocus();
});

test('a 500-entry Video queue has zero panel commits during 500 elapsed-clock updates', async () => {
  const audio = new AsideAudio();
  const store = createPlayerStore({ audioFactory: () => audio, mediaSession: null });
  stores.push(store);
  const largeQueue = Array.from({ length: 500 }, (_, index) => ({
    ...tracks[0], id: `large-${index}`, title: `Track ${index}`, mediaType: 'video' as const,
    streamUrl: `/video/${index}.mp4`, artworkUrl: ''
  }));
  await store.launchQueue(largeQueue, 0, { autoplay: false });
  const onRender = vi.fn();
  render(<Profiler id="queue" onRender={onRender}><NowPlayingAside store={store} /></Profiler>);
  expect(screen.getAllByRole('listitem')).toHaveLength(499);
  onRender.mockClear();

  for (let tick = 1; tick <= 500; tick += 1) {
    act(() => { audio.currentTime = tick; audio.emit('timeupdate'); });
  }

  expect(store.getSnapshot().currentTime).toBe(500);
  expect(onRender.mock.calls.length).toBe(0);
  act(() => { store.toggleShuffle(); });
  expect(onRender).toHaveBeenCalledTimes(1);
  expect(screen.getByText('Shuffled order')).toBeInTheDocument();
  await act(async () => { await store.next(); });
  expect(screen.getByRole('heading', { name: store.getSnapshot().currentItem!.title })).toBeInTheDocument();
}, 30_000);
